// German — the console's default locale and the one every other locale is held to
// (ADR-0267, ADR-0497).
//
// Messages are keyed by id: a dotted path naming the screen and then the thing —
// `tasks.folders.save` — so a screen's strings sit together and an unused one is
// findable. A message may carry {placeholders}, and plain markup where the screen
// inserts it as HTML; it is shipped with the console, never loaded from elsewhere.
// A counted message has a form per plural category of the language (`.one` and
// `.other` here), chosen by Intl.PluralRules.
//
// Every other locale carries exactly these keys; a test holds it to that.
