  "content.quarantineHint": "Beschreibung, Suchwörter und Bild sind überall ausserhalb dieser Seite zurückgehalten — im Shop, auf der Genehmigung, in den Bestellungen, über die API und MCP. Name und Preis bleiben. Die Quarantäne endet erst, wenn ein Aktualisieren jede Regel besteht; eine Prüfung, die von selbst wieder besteht, hebt sie nicht auf. Solange sie besteht, lässt sich der Katalog nicht veröffentlichen.",
