  "connections.list.title": "Verbindungen",
  "connections.list.intro": "Eine Verbindung ist die Erlaubnis, dass ausgewählte Worker mit deinem Konto handeln – jedes Mal nur, wenn eine Policy die konkrete Aktion erlaubt.",
  "connections.list.empty": "Keine Verbindungen.",
