  "connections.workers.savedNone": "Gespeichert – kein Worker darf diese Verbindung verwenden",
  "connections.revoke": "Widerrufen",
  "connections.revoke.confirm": "Diese Verbindung widerrufen?\n\nDie Zugangsdaten werden gelöscht, und kein Worker kann danach mehr in deinem Namen handeln. Rückgängig machen lässt es sich nicht; du kannst das Konto aber neu verknüpfen.",
  "connections.revoked": "Verbindung widerrufen",

  // Approvals (ADR-0475 §9). approvals_page_internal_test.go holds the page to these
  // keys in both languages.
  "approvals.title": "Genehmigungen",
  "approvals.intro": "Hier beantwortest du Genehmigungen, die eine Policy für eine bestimmte Aktion verlangt, etwa das Löschen eines Dokuments in SharePoint. Eine Genehmigung gilt genau für die angezeigte Aktion; ändert sich etwas daran, zählt sie nicht.",
  "approvals.after": "Deine Antwort führt die Aktion nicht aus. Die Policy prüft die Antworten, wenn die Aktion das nächste Mal versucht wird; wann das ist, bestimmt der Prozess.",
  "approvals.signIn": "Genehmigungen beantworten angemeldete Personen. Auf diesem Server ist die Anmeldung ausgeschaltet, deshalb gibt es hier nichts zu beantworten.",
  "approvals.denied": "Genehmigungen beantworten Personen in ihrer eigenen Sitzung. Mit dieser Anmeldung gibt es keine Liste.",
  "approvals.truncated": "Es sind mehr Genehmigungen offen, als eine Seite fasst. Angezeigt werden die {n}, die am frühesten ablaufen.",
  "approvals.waiting.title": "Warten auf deine Antwort",
  "approvals.waiting.intro": "Du bist in der Gruppe, die diese Aktionen freigeben darf.",
  "approvals.waiting.empty": "Keine Genehmigung wartet auf deine Antwort.",
  "approvals.answered.title": "Von dir beantwortet",
  "approvals.answered.intro": "Solange eine Genehmigung offen ist, kannst du deine Antwort zurückziehen und neu geben.",
  "approvals.answered.empty": "Du hast keine offene Genehmigung beantwortet.",
  "approvals.onBehalf.title": "Für dich angefragt",
  "approvals.onBehalf.intro": "Diese Aktionen würden in deinem Namen ausgeführt. Freigeben kann sie nur jemand anderes.",
  "approvals.standing.rejected": "abgelehnt",
  "approvals.standing.count": "{granted} von {needed} Freigaben",
  "approvals.answer.granted": "freigegeben",
  "approvals.answer.rejected": "abgelehnt",
  "approvals.answer.withdrawn": "Antwort zurückgezogen",
  "approvals.answer.reason": "„{reason}“",
  "approvals.self": "Diese Aktion würde für dich ausgeführt. Niemand gibt eine Aktion für sich selbst frei; antworten kann ein Mitglied der Gruppe {group}.",
  "approvals.mine.granted": "Du hast freigegeben",
  "approvals.mine.rejected": "Du hast abgelehnt",
  "approvals.withdraw": "Antwort zurückziehen",
  "approvals.reason": "Begründung (freiwillig)",
