  "approvals.digest": "Fingerabdruck",
  "approvals.digest.title": "Der Fingerabdruck der Aktion. Die Genehmigung gilt nur für die Aktion mit genau diesem Fingerabdruck.",
  "approvals.grant.confirm": "Diese Aktion freigeben?\n\n{operation} {resource}\nfür {who}, ausgeführt von {worker}\n\nDie Freigabe gilt nur für genau diese Aktion.",
  "approvals.reject.confirm": "Diese Aktion ablehnen?\n\n{operation} {resource}\nfür {who}\n\nSolange deine Ablehnung steht, verhindert sie die Aktion, auch wenn andere freigegeben haben.",
  "approvals.withdraw.confirm": "Deine Antwort zurückziehen?\n\n{operation} {resource}\n\nDanach zählt sie nicht mehr. Solange die Genehmigung offen ist, kannst du neu antworten.",
