  // The BPMN properties panel: the FEEL field, the script editor, the fx toggle, the documentation field, the retry budget and the database Worker Types (editor.js, feel.js), and the references in the replay's Variables tab (varrefs.js).
  "pnl.feel.hint": "FEEL — <kbd>Ctrl</kbd>+<kbd>Leertaste</kbd> für Vervollständigung · <kbd>F2</kbd> Entwickleransicht",
  "pnl.feel.test.button": "Testen",
  "pnl.feel.test.buttonTitle": "Diesen Ausdruck mit Beispielvariablen testen",
