  "pnl.feel.ref.accountGone": "Hier gibt es kein aktiviertes Konto mit dieser ID. Es wurde gelöscht — die Instanz behält die ID als Nachweis, wer es war — oder es ist deaktiviert, was das Verzeichnis ebenfalls nicht aufführt.",
