  "pnl.ops.exchange.hint.values": "Ein String, der mit = beginnt, ist ein FEEL-Ausdruck; true, false und Zahlen bleiben, was sie sind (ein Switch braucht einen Boolean). Ein Wert, der null ergibt, wird weggelassen und nie als Löschung gesendet.",
  "pnl.ops.exchange.result.list": "Ein Array von Objekten (leer, wenn es keine gibt), höchstens maxResults lang — eine Auflistung, die darüber hinausgeht, schlägt fehl, statt gekürzt zu werden.",
  "pnl.ops.exchange.result.get": "Ein Objekt mit den Eigenschaften des Cmdlets, oder null, wenn es keines gibt. Eine Identität, die auf mehrere Objekte passt, lässt die Task fehlschlagen.",
  "pnl.ops.exchange.result.object": "Das Objekt, das das Cmdlet angelegt oder erteilt hat — oder jeder Eintrag, wenn Exchange mit mehreren antwortet — für ein Modell, das es behält; leer lassen, um es zu verwerfen.",
  "pnl.ops.contacts.maxHint": "Begrenzt, was in der Ergebnisvariable landen darf, höchstens {max}. Ein Ergebnis mit mehr lässt die Task fehlschlagen, statt gekürzt zu werden, denn eine gekürzte Liste ist eine falsche Antwort, nach der ein Prozess handeln würde. Leer verwendet {default}.",
  "pnl.ops.contacts.result.list": "Eine Liste von Kontakten, jeder das Objekt, das «Kontakt lesen» liefert; leer, wenn nichts passte. FEEL-Listen beginnen bei 1, der erste ist also =kunden[1].",
  "pnl.ops.contacts.query.find": "Eine E-Mail-Adresse oder eine Telefonnummer, exakt verglichen (eine Adresse ohne Rücksicht auf Gross-/Kleinschreibung, eine Nummer nach ihren Ziffern) — oder, mit einem unten genannten benutzerdefinierten Feld, dessen Wert. «Kontakte finden» liest das Adressbuch selbst, also wird auch ein Kontakt gefunden, der vor einer Minute angelegt wurde. Meist ein FEEL-Ausdruck (fx), z. B. =anfrage.absender.",
