  "pnl.ops.carddav.result.get": "Der Kontakt als ein Objekt: id, displayName, givenName, familyName, email, emails, phone, phones, organization, jobTitle, department, address, addresses, birthday, notes, fields (die X-Eigenschaften der Karte nach Name) und groups. Ein Schlüssel, für den der Kontakt keinen Wert hat, ist null, eine Liste leer — dieselbe Form wie ein Kontakt aus Google Contacts.",
  "pnl.ops.carddav.result.saved": "Der Kontakt, wie das Adressbuch ihn danach führt, mit seiner id — behalte ihn, um den Kontakt später anzusprechen. Leer lassen, um ihn zu verwerfen.",
